## Animation & State Management
- Use `useRef` to store mutable physics state (positions, velocities).
- Use a custom `useAnimationFrame` hook wrapping `requestAnimationFrame`.
- Global simulation state managed in `App.tsx` via `useState`.

```ts
// hooks/useAnimationFrame.ts
export function useAnimationFrame(callback: (delta: number) => void) {
  let lastTime = performance.now();
  function loop(time: number) {
    const delta = time - lastTime;
    lastTime = time;
    callback(delta);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
}
```

