## 4. Core Component Requirements

### 4.1 SpectatorSystem Class
```typescript
class SpectatorSystem {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private spectators: Spectator[] = [];
  private rows: SpectatorRow[] = [];
  private atmosphereMetrics: AtmosphereMetrics;

  constructor(canvasId: string, config: {
    rowCount: number; // 8-12 rows
    seatsPerRow: number; // 40-60 seats
    teamColors: { home: string; away: string }; // Hex: #FF0000, #0000FF
  });

  public triggerEvent(event: GameEvent): void;
  public update(deltaTime: number): void;
  public render(): void;
  public getAtmosphereLevel(): number;
}
```

### 4.2 Spectator Class
```typescript
class Spectator {
  private config: SpectatorConfig;
  private state: SpectatorState;
  private animationTimer: number = 0;

  constructor(config: SpectatorConfig);

  public react(event: GameEvent, intensity: number): void;
  public update(deltaTime: number): void;
  public draw(ctx: CanvasRenderingContext2D): void;

  // Animation methods
  private animateCheer(): void; // Arms up, jump
  private animateBoo(): void; // Arms down, slouch
  private animateWave(): void; // Sequential arm raise
  private animateIdle(): void; // Subtle movement
}
```

### 4.3 AudioManager Class
```typescript
class AudioManager {
  private audioContext: AudioContext;
  private masterGain: GainNode;
  private oscillators: Map<string, OscillatorNode> = new Map();
  private config: AudioConfig;

  constructor(config: AudioConfig);

  public playCheer(intensity: number, duration: number): void;
  public playBoo(intensity: number, duration: number): void;
  public playAmbient(volume: number): void;
  public stopAll(): void;

  // Synthesized crowd sounds using Web Audio API
  private createCrowdNoise(frequency: number, volume: number): void;
  private createCheerWave(baseFreq: number, modulation: number): void;
}
```

